window.onCleanup = window.onCleanup || function(){};
window.signal = window.signal;
window.root = document.querySelector('[data-page-id="nuvio"]') || document;

(() => {
  const initialRoute = "/login";

  function showRoute() {
    const pages = [...document.querySelectorAll("[data-prototype-page]")];
    const route = location.hash.slice(1) || initialRoute;
    const active = pages.find((page) => page.dataset.route === route) || pages[0];
    if (!active) return;
    for (const page of pages) page.hidden = page !== active;
    document.querySelectorAll("dialog[open]").forEach(function(d){try{d.close();}catch(e){}});
    for (const link of document.querySelectorAll("[data-route-link]")) {
      const current = link.getAttribute("href") === "#" + active.dataset.route;
      if (current) link.setAttribute("aria-current", "page");
      else link.removeAttribute("aria-current");
    }
  }

  addEventListener("hashchange", showRoute);
  showRoute();
})();

/* src/components/kravio-range.component.html */
(() => { document.addEventListener('change', event => {
    const el = event.target.closest('[data-action="kravio-range:change"]');
    if (!el) return;
    const component = el.closest('[data-component="kravio-range"]');
    component.dispatchEvent(new CustomEvent('kravio:range', { bubbles:true, detail:{target:component.dataset.target,value:el.value} }));
  }); })();

/* src/components/kravio-metric.component.html */
(() => {
  document.addEventListener('kravio:range',event=>{
    if(event.detail.target!=='dashboard')return;
    const page=event.target.closest('[data-node-id="nuvio.dashboard"]');if(!page)return;
    const fixtures={'Last week':['42','7','8'],'Last month':['156','12','21'],'Last quarter':['418','9','34']};
    page.querySelectorAll('[data-component="kravio-metric"]').forEach(el=>{const i=['tickets','resolution','compliance'].indexOf(el.dataset.metric);el.querySelector('[data-part="value"]').textContent=fixtures[event.detail.value][i];});
  });
})();

/* src/components/kravio-metric.component.html */
(() => {

  const running = new WeakMap();
  function reveal(element, token = '--duration-normal', delay = 0, frames) {
    if (!element) return;
    running.get(element)?.cancel();
    if (matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    const style = getComputedStyle(element);
    const animation = element.animate(frames || [
      { opacity: .35, transform: 'translateY(4px)' },
      { opacity: 1, transform: 'translateY(0)' }
    ], {
      duration: parseFloat(style.getPropertyValue(token)) || 0,
      delay,
      easing: style.getPropertyValue('--ease-standard').trim(),
      fill: 'none'
    });
    running.set(element, animation);
  }

  document.addEventListener('kravio:range', event => {
    if (event.detail.target !== 'dashboard') return;
    const page = event.target.closest('[data-node-id="nuvio.dashboard"]');
    page?.querySelectorAll('[data-component="kravio-metric"]').forEach(host => {
      reveal(host.querySelector('[data-part="value"]'));
    });
  });
})();

/* src/components/kravio-sidebar.component.html */
(() => {
  const ROUTES = {
    "my workspace": "/my-workspace", "my tasks": "/my-workspace",
    "dashboard": "/dashboard", "my projects": "/dashboard",
    "my approvals": "/crm-sales", "my approval": "/crm-sales", "crm sales": "/crm-sales",
    "my activities": "/business-development", "my calendar": "/quotation", "my documents": "/sales",
    "my notifications": "/projects", "my email": "/purchase", "my profile": "/inventory",
    "finance accounting": "/finance", "reports analytics": "/reports", "management executive": "/management",
    "master data": "/master-data", "document management": "/document-management", "document template": "/document-template",
    "email communication": "/email-communication", "omnichannel": "/omnichannel", "whatsapp integration": "/whatsapp-integration",
    "general meeting rups": "/general-meeting-rups", "workflow approval": "/workflow-approval", "corporate": "/corporate",
    "ai assistant": "/ai-assistant", "data intelligence": "/data-intelligence", "integrations": "/integrations",
    "security audit": "/security-audit", "settings": "/settings",
    "overview": "/overview", "nuvio support dashboard": "/overview", "support dashboard": "/overview"
  };
  const GROUP_ROUTES = {
    "my workspace": "/my-workspace", "dashboard": "/dashboard", "crm sales": "/crm-sales",
    "business development": "/business-development", "quotation": "/quotation", "sales": "/sales",
    "project": "/projects", "purchase": "/purchase", "inventory": "/inventory",
    "finance accounting": "/finance", "reports analytics": "/reports", "management executive": "/management",
    "master data": "/master-data", "document management": "/document-management", "document template": "/document-template",
    "email communication": "/email-communication", "omnichannel": "/omnichannel", "whatsapp integration": "/whatsapp-integration",
    "general meeting rups": "/general-meeting-rups", "workflow approval": "/workflow-approval", "corporate": "/corporate",
    "ai assistant": "/ai-assistant", "data intelligence": "/data-intelligence", "integrations": "/integrations",
    "security audit": "/security-audit", "settings": "/settings"
  };
  const norm = (s) => String(s || "").toLowerCase().replace(/&/g, " ").replace(/[^a-z0-9]+/g, " ").trim();
  const go = (route) => { if (!route) return false; try { if (("#" + route) !== location.hash) location.hash = "#" + route; } catch (err) {} return true; };
  const routeFor = (label) => ROUTES[norm(label)] || GROUP_ROUTES[norm(label)];
  const syncActive = () => {
    const route = location.hash.slice(1);
    document.querySelectorAll('[data-component="kravio-sidebar"]').forEach(host => {
      const items = [...host.querySelectorAll('nav button[data-action="kravio-sidebar:navigate"]')];
      items.forEach(b => b.removeAttribute('aria-current'));
      if (!route) return;
      const target = items.find(b => routeFor((b.getAttribute('title') || b.textContent || '').trim()) === route);
      if (target) target.setAttribute('aria-current', 'page');
    });
  };
  window.addEventListener('hashchange', syncActive);
  syncActive();
  document.addEventListener("input",event=>{
    if(!event.target.matches("[data-action=\"kravio-sidebar:search\"]")) return;
    const host=event.target.closest("[data-component=\"kravio-sidebar\"]"); const query=event.target.value.toLowerCase();
    host.querySelectorAll("nav button").forEach(el=>el.hidden=!el.textContent.toLowerCase().includes(query));
  });
  document.addEventListener("click",event=>{
    const host=event.target.closest("[data-component=\"kravio-sidebar\"]"); if(!host) return;
    const nav=event.target.closest('[data-action="kravio-sidebar:navigate"]'); if(!nav) return;
    const label=(nav.getAttribute("title")||nav.textContent||"").trim();
    const route=routeFor(label);
    if(route){ go(route); return; }
    host.dispatchEvent(new CustomEvent("kravio:navigate",{bubbles:true,detail:{label}}));
  });
})();

/* src/components/kravio-chart.component.html */
(() => {
  function inspect(el){const host=el.closest('[data-component="kravio-chart"]');host.querySelectorAll('[data-action="kravio-chart:inspect"]').forEach(b=>b.setAttribute('aria-pressed',String(b===el)));const plot=host.querySelector('[data-part="plot"]');const marker=host.querySelector('[data-part="marker"]');marker.style.top=(100-Number(el.dataset.value)/900*100)+'%';marker.style.left=Math.min(85,Math.max(25,(el.offsetLeft+el.offsetWidth/2)/plot.clientWidth*100))+'%';host.querySelector('[data-part="tooltip"]').textContent=el.dataset.day+': '+el.dataset.value;}
  for(const eventName of ['click','focusin','pointerover'])document.addEventListener(eventName,event=>{const el=event.target.closest('[data-action="kravio-chart:inspect"]');if(el)inspect(el);});
  document.addEventListener('keydown',event=>{const el=event.target.closest('[data-action="kravio-chart:inspect"]');if(!el||!['ArrowLeft','ArrowRight'].includes(event.key))return;event.preventDefault();const sibling=event.key==='ArrowRight'?el.nextElementSibling:el.previousElementSibling;if(sibling)sibling.focus();});
  document.addEventListener('kravio:range',event=>{if(event.detail.target!=='trend')return;const host=event.target.closest('[data-component="kravio-chart"]');const factor={'Last week':1,'Last month':1.12,'Last quarter':.88}[event.detail.value];host.querySelector('[data-part="total"]').textContent=({'Last week':'4,790','Last month':'19,160','Last quarter':'57,480'})[event.detail.value];const values=[286,584,676,399,538,584,462,584,765,676,626,676,353,714,525];host.querySelectorAll('[data-action="kravio-chart:inspect"]').forEach((el,i)=>{const value=Math.round(values[i]*factor);el.dataset.value=value;el.style.setProperty('--bar-height',value/900*100+'%');el.setAttribute('aria-label',el.dataset.day+': '+value+' tickets');});inspect(host.querySelector('[aria-pressed="true"]'));});
})();

