/* src/components/kravio-updates.component.html */
(() => {
  function filter(host){const query=host.querySelector('input').value.toLowerCase();let count=0;host.querySelectorAll('[data-part="list"] > [data-period]').forEach(el=>{el.hidden=!(host.dataset.period==='week'||el.dataset.period===host.dataset.period)||!el.textContent.toLowerCase().includes(query);if(!el.hidden)count++;});host.querySelector('[data-part="count"]').innerHTML='<strong>'+count+'</strong> '+({today:'aktivitas baru hari ini',yesterday:'aktivitas kemarin',week:'aktivitas minggu ini'})[host.dataset.period];host.querySelector('[data-part="empty"]').hidden=count>0;}
  document.addEventListener('input',event=>{if(event.target.matches('[data-action="kravio-updates:search"]'))filter(event.target.closest('[data-component="kravio-updates"]'));});
  document.addEventListener('click',event=>{const el=event.target.closest('[data-action="kravio-updates:period"]');if(!el)return;const host=el.closest('[data-component="kravio-updates"]');host.dataset.period=el.dataset.period;host.querySelectorAll('[data-action="kravio-updates:period"]').forEach(b=>b.setAttribute('aria-pressed',String(b===el)));filter(host);});
})();

/* src/components/kravio-updates.component.html */
(() => {
  const running = new WeakMap();
  function reveal(element, token = '--duration-normal', delay = 0, frames) {
    if (!element) return;
    running.get(element)?.cancel();
    if (matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    const style = getComputedStyle(element);
    const animation = element.animate(frames || [
      { opacity: .35, transform: 'translateY(4px)' },
      { opacity: 1, transform: 'translateY(0)' }
    ], {
      duration: parseFloat(style.getPropertyValue(token)) || 0,
      delay,
      easing: style.getPropertyValue('--ease-standard').trim(),
      fill: 'none'
    });
    running.set(element, animation);
  }

  function update(event) {
    const control = event.target.closest('[data-action="kravio-updates:period"], [data-action="kravio-updates:search"]');
    if (!control) return;
    const host = control.closest('[data-component="kravio-updates"]');
    const fast = event.type === 'input';
    const stagger = fast ? 0 : parseFloat(getComputedStyle(host).getPropertyValue('--duration-stagger')) || 0;
    queueMicrotask(() => {
      host.querySelectorAll('[data-part="list"] > [data-period]:not([hidden])').forEach((item, index) => reveal(item, fast ? '--duration-fast' : '--duration-normal', Math.min(index, 5) * stagger));
      reveal(host.querySelector('[data-part="count"]'), '--duration-fast');
      if (!host.querySelector('[data-part="empty"]').hidden) reveal(host.querySelector('[data-part="empty"]'));
    });
  }
  document.addEventListener('click', update);
  document.addEventListener('input', update);
})();

/* src/components/kravio-table.component.html */
(() => {
  const hostOf=el=>el.closest('[data-component="kravio-table"]');
  const st=host=>{if(!host.__pg)host.__pg={page:1,size:Number(host.querySelector('[data-action="kravio-table:size"]').value)||5};return host.__pg;};
  function matchedRows(host){
    const query=host.querySelector('[data-action="kravio-table:search"]').value.toLowerCase();
    const chosen=type=>[...host.querySelectorAll('[data-filter="'+type+'"]:checked')].map(x=>x.value);
    const priorities=chosen('priority'),statuses=chosen('status');
    return [...host.querySelectorAll('tbody tr')].filter(row=>(!query||row.textContent.toLowerCase().includes(query))&&(!priorities.length||priorities.includes(row.dataset.priority))&&(!statuses.length||statuses.includes(row.dataset.status)));
  }
  function updateSelection(host){const boxes=[...host.querySelectorAll('tbody tr:not([hidden]) [data-action="kravio-table:select"]')];const all=host.querySelector('[data-action="kravio-table:all"]');all.checked=boxes.length>0&&boxes.every(b=>b.checked);all.indeterminate=boxes.some(b=>b.checked)&&!all.checked;}
  function pageButtons(total,current){if(total<=1)return '';const out=[];const push=n=>out.push('<button type="button" class="c-kravio-table__page-num" data-action="kravio-table:goto" data-page="'+n+'" aria-current="'+(n===current)+'">'+n+'</button>');const dots=()=>out.push('<span class="c-kravio-table__page-dots">…</span>');
    if(total<=7){for(let i=1;i<=total;i++)push(i);}
    else{push(1);if(current>3)dots();for(let i=Math.max(2,current-1);i<=Math.min(total-1,current+1);i++)push(i);if(current<total-2)dots();push(total);}
    return out.join('');}
  function render(host){
    const state=st(host);const rows=[...host.querySelectorAll('tbody tr')];const matches=matchedRows(host);
    const pages=Math.max(1,Math.ceil(matches.length/state.size));if(state.page>pages)state.page=pages;if(state.page<1)state.page=1;
    const start=(state.page-1)*state.size,end=start+state.size;
    rows.forEach(r=>r.hidden=true);matches.slice(start,end).forEach(r=>r.hidden=false);
    host.querySelector('[data-part="page-info"]').textContent=matches.length?('Menampilkan '+(start+1)+'–'+Math.min(end,matches.length)+' dari '+matches.length+' record'+(pages>1?(' · halaman '+state.page+'/'+pages):'')):'Tidak ada record';
    host.querySelector('[data-part="page-numbers"]').innerHTML=pageButtons(pages,state.page);
    host.querySelector('[data-action="kravio-table:first"]').disabled=state.page<=1;
    host.querySelector('[data-action="kravio-table:prev"]').disabled=state.page<=1;
    host.querySelector('[data-action="kravio-table:next"]').disabled=state.page>=pages;
    host.querySelector('[data-action="kravio-table:last"]').disabled=state.page>=pages;
    host.querySelector('[data-part="empty"]').hidden=matches.length>0;
    const filtersActive=!!host.querySelector('[data-action="kravio-table:search"]').value||host.querySelectorAll('[data-filter]:checked').length>0;
    host.querySelector('[data-part="feedback"]').hidden=!filtersActive;
    host.querySelector('[data-part="result-count"]').textContent=matches.length+' dari '+rows.length+' record';
    updateSelection(host);
  }
  document.addEventListener('input',event=>{if(event.target.matches('[data-action="kravio-table:search"]')){const host=hostOf(event.target);st(host).page=1;render(host);}});
  document.addEventListener('change',event=>{const host=hostOf(event.target);if(!host)return;
    if(event.target.matches('[data-filter]')){st(host).page=1;render(host);}
    if(event.target.matches('[data-action="kravio-table:size"]')){st(host).size=Number(event.target.value);st(host).page=1;render(host);}
    if(event.target.matches('[data-action="kravio-table:all"]'))host.querySelectorAll('tbody tr:not([hidden]) input[type="checkbox"]').forEach(b=>b.checked=event.target.checked);
    updateSelection(host);});
  document.addEventListener('click',event=>{
    const el=event.target.closest('[data-action]');if(!el)return;const host=hostOf(el);if(!host)return;
    const state=st(host);const pages=Math.max(1,Math.ceil(matchedRows(host).length/state.size));
    if(el.dataset.action==='kravio-table:reset'){host.querySelector('[data-action="kravio-table:search"]').value='';host.querySelectorAll('[data-filter]').forEach(x=>x.checked=false);state.page=1;render(host);}
    if(el.dataset.action==='kravio-table:size'){/* handled on change */}
    if(el.dataset.action==='kravio-table:first'){state.page=1;render(host);}
    if(el.dataset.action==='kravio-table:prev'){state.page=Math.max(1,state.page-1);render(host);}
    if(el.dataset.action==='kravio-table:next'){state.page=Math.min(pages,state.page+1);render(host);}
    if(el.dataset.action==='kravio-table:last'){state.page=pages;render(host);}
    if(el.dataset.action==='kravio-table:goto'){state.page=Number(el.dataset.page);render(host);}
    if(el.dataset.action==='kravio-table:sort'){const col=Number(el.dataset.column),th=el.closest('th'),ascending=th.getAttribute('aria-sort')!=='ascending';host.querySelectorAll('th[aria-sort]').forEach(h=>h.setAttribute('aria-sort','none'));th.setAttribute('aria-sort',ascending?'ascending':'descending');const rows=[...host.querySelectorAll('tbody tr')];rows.sort((a,b)=>a.cells[col].textContent.trim().localeCompare(b.cells[col].textContent.trim(),undefined,{numeric:true})*(ascending?1:-1));host.querySelector('tbody').append(...rows);render(host);}
    if(el.dataset.action==='kravio-table:detail'){const row=el.closest('tr');host.dispatchEvent(new CustomEvent('kravio:detail',{bubbles:true,detail:{title:'Record '+row.dataset.record,description:row.cells[1].textContent,fields:[...row.cells].slice(2,7).map(c=>c.textContent.trim()).join(' · ')}}));}
    if(el.dataset.action==='kravio-table:export'){const rows=[['Record','Deskripsi','Prioritas','Owner','Status','Modul','Deadline'],...matchedRows(host).map(r=>[...r.cells].slice(0,7).map(c=>c.textContent.trim()))];const csv=rows.map(r=>r.map(v=>'"'+v.replaceAll('"','""')+'"').join(',')).join(String.fromCharCode(13,10));const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));const link=document.createElement('a');link.href=url;link.download='sop-records.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);host.dispatchEvent(new CustomEvent('kravio:notice',{bubbles:true,detail:{message:'CSV record SOP diekspor.'}}));}
  });
  document.addEventListener('keydown',event=>{if(event.key==='Escape'){const host=hostOf(event.target);const details=host?.querySelector('details[open]');if(details){details.open=false;details.querySelector('summary').focus();}}});
  document.addEventListener('click',event=>document.querySelectorAll('[data-component="kravio-table"] details[open]').forEach(el=>{if(!el.contains(event.target))el.open=false;}));
  document.querySelectorAll('[data-component="kravio-table"]').forEach(render);
})();

/* src/components/kravio-table.component.html */
(() => {
  const running = new WeakMap();
  function reveal(element, token = '--duration-normal', delay = 0, frames) {
    if (!element) return;
    running.get(element)?.cancel();
    if (matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    const style = getComputedStyle(element);
    const animation = element.animate(frames || [
      { opacity: .35, transform: 'translateY(4px)' },
      { opacity: 1, transform: 'translateY(0)' }
    ], {
      duration: parseFloat(style.getPropertyValue(token)) || 0,
      delay,
      easing: style.getPropertyValue('--ease-standard').trim(),
      fill: 'none'
    });
    running.set(element, animation);
  }

  function update(event) {
    const control = event.target.closest('[data-action="kravio-table:sort"], [data-action="kravio-table:reset"], [data-action="kravio-table:search"], [data-action="kravio-table:goto"], [data-action="kravio-table:prev"], [data-action="kravio-table:next"], [data-action="kravio-table:first"], [data-action="kravio-table:last"], [data-filter]');
    const host = control?.closest('[data-component="kravio-table"]');
    if (!host) return;
    const rows = [...host.querySelectorAll('tbody tr:not([hidden])')];
    const before = new Map(rows.map(row => [row, row.getBoundingClientRect().top]));
    queueMicrotask(() => {
      host.querySelectorAll('tbody tr:not([hidden])').forEach(row => {
        const delta = (before.get(row) ?? row.getBoundingClientRect().top) - row.getBoundingClientRect().top;
        if (control.dataset.action === 'kravio-table:sort') {
          reveal(row, '--duration-panel', 0, [{ transform: 'translateY(' + delta + 'px)' }, { transform: 'translateY(0)' }]);
        } else reveal(row, '--duration-fast', 0, [{ opacity: .4 }, { opacity: 1 }]);
      });
      if (!host.querySelector('[data-part="empty"]').hidden) reveal(host.querySelector('[data-part="empty"]'));
    });
  }
  document.addEventListener('click', update, true);
  document.addEventListener('input', update, true);
  document.addEventListener('change', update, true);
})();

/* src/components/nuvio-topbar.component.html */
(() => {
  const findDashboard = () => document.querySelector('.dashboard');
  const applyTheme = dark => {
    document.querySelectorAll('.dashboard').forEach(dashboard => { dashboard.dataset.theme = dark ? 'dark' : 'light'; });
    document.querySelectorAll('[data-action="nuvio:theme"]').forEach(btn => {
      btn.setAttribute('aria-pressed', String(dark));
      btn.setAttribute('aria-label', dark ? 'Aktifkan mode terang' : 'Aktifkan mode gelap');
      const icon = btn.querySelector('iconify-icon');
      if (icon) icon.setAttribute('icon', dark ? 'lucide:sun' : 'lucide:moon');
    });
  };
  try { if (localStorage.getItem('sop-theme') === 'dark') applyTheme(true); } catch {}

  document.addEventListener('click', event => {
    const el = event.target.closest('[data-action="nuvio:theme"]');
    if (!el) return;
    const dashboard = el.closest('.dashboard');
    const dark = dashboard ? dashboard.dataset.theme !== 'dark' : true;
    applyTheme(dark);
    try { localStorage.setItem('sop-theme', dark ? 'dark' : 'light'); } catch {}
  });

  document.addEventListener('change', event => {
    const el = event.target.closest('[data-action="nuvio:lang"]');
    if (!el) return;
    const lang = el.value;
    const dashboard = findDashboard();
    if (dashboard) dashboard.setAttribute('lang', lang);
    document.documentElement.lang = lang;
    document.dispatchEvent(new CustomEvent('nuvio:langchange', { detail: { lang } }));
    try { localStorage.setItem('sop-lang', lang); } catch {}
  });

  try {
    const savedLang = localStorage.getItem('sop-lang');
    if (savedLang === 'en') {
      const select = document.querySelector('[data-action="nuvio:lang"]');
      if (select) { select.value = 'en'; select.dispatchEvent(new Event('change', { bubbles: true })); }
    }
  } catch {}
})();

/* src/pages/nuvio.page.html */
const dashboard=root.querySelector('.dashboard');
 const dialog=root.querySelector('dialog');
 let toastTimer;
 const notice=message=>{const toast=root.querySelector('.toast');toast.textContent=message;toast.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.hidden=true,3500);};
 const show=(title,description,fields='')=>{dialog.querySelector('[data-detail="title"]').textContent=title;dialog.querySelector('[data-detail="description"]').textContent=description;dialog.querySelector('[data-detail="fields"]').textContent=fields;dialog.showModal();};
 root.addEventListener('kravio:notice',event=>notice(event.detail.message),{signal});
 root.addEventListener('kravio:detail',event=>show(event.detail.title,event.detail.description,event.detail.fields),{signal});
 root.addEventListener('kravio:navigate',event=>{
 const label=(event.detail&&event.detail.label?event.detail.label:'').trim();
 if(label==='Overview'){window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return;}
 show(label,'Bagian ini diwakili oleh navigasi pada workspace SOP.','Gunakan My Workspace untuk melihat ringkasan pekerjaan hari ini.');
 },{signal});
 root.addEventListener('click',event=>{
 const el=event.target.closest('[data-action]');if(!el)return;
 const action=el.dataset.action;
 if(action==='kravio:sidebar'){const mobile=matchMedia('(max-width:760px)').matches;const cur=dashboard.dataset.sidebar;const next=mobile?(cur==='open'?'closed':'open'):(cur==='collapsed'?'default':'collapsed');dashboard.dataset.sidebar=next;el.setAttribute('aria-expanded',String(next!=='closed'));}
 if(action==='kravio:notifications')show(t('Notifikasi'),t('7 item membutuhkan perhatian'),t('Approval quotation Q-2026-014 · PR-331 menunggu budget check · Invoice INV-088 three-way match · RUPS reminder.'));
 if(action==='kravio:settings')show(t('Settings'),t('SOP workspace'),t('Signed in as Aditya Pratama · aditya.pratama@example.com'));
 if(action==='kravio:profile')show('Aditya Pratama','aditya.pratama@example.com',t('Workspace: SOP · Status: Online'));
 if(action==='sop:create')show(t('Buat ')+t(el.dataset.kind),t('Draft dibuat dengan validasi dan approval sesuai policy.'),t('Record memiliki owner, status, nomor, dan audit trail.'));
 if(action==='sop:drill')show(t(el.dataset.kind),t('KPI drill-down ke list terfilter.'),t('Filter date, company, branch, department, project, owner, currency aktif.'));
 if(action==='sop:approve')notice(t('Record disetujui. Next step dijalankan dan audit event dicatat.'));
 if(action==='sop:reject')notice(t('Record ditolak dengan reason. Owner menerima notifikasi.'));
 if(action==='kravio:close')dialog.close();
 if(action==='kravio:refresh')notice(t('Workspace diperbarui. Data contoh sudah paling baru.'));
 if(action==='kravio:print')window.print();
 if(action==='kravio:reset'){root.querySelectorAll('[data-action="kravio-range:change"]').forEach(select=>{select.value='Minggu ini';select.dispatchEvent(new Event('change',{bubbles:true}));});notice(t('Filter direset ke minggu ini.'));}
 if(['kravio:refresh','kravio:print','kravio:reset'].includes(action))root.querySelector('.options').open=false;
 },{signal});
 root.addEventListener('keydown',event=>{if(event.key==='Escape'){if(matchMedia('(max-width:760px)').matches)dashboard.dataset.sidebar='closed';root.querySelectorAll('details[open].options').forEach(el=>el.open=false);}}, {signal});
 dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}}, {signal});
 document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();dashboard.dataset.sidebar='open';root.querySelector('[data-action="kravio-sidebar:search"]').focus();}}, {signal});
 root.addEventListener('click',event=>{root.querySelectorAll('.options[open]').forEach(el=>{if(!el.contains(event.target))el.open=false;});},{signal});

