  const spark = (points, tone) => {
    const w = 90, h = 40, max = Math.max(...points), min = Math.min(...points);
    const span = (max - min) || 1;
    const coords = points.map((p, i) => { const x = (i / (points.length - 1)) * w; const y = h - 4 - ((p - min) / span) * (h - 8); return [x.toFixed(1), y.toFixed(1)]; });
    const line = coords.map(c => c.join(',')).join(' ');
    const last = coords[coords.length - 1];
    return '<svg class="kpi__spark" viewBox="0 0 ' + w + ' ' + h + '" preserveAspectRatio="none" aria-hidden="true"><polygon class="kpi__spark-area" points="' + line + ' ' + w + ',' + h + ' 0,' + h + '"></polygon><polyline class="kpi__spark-line" points="' + line + '"></polyline><circle class="kpi__spark-dot" cx="' + last[0] + '" cy="' + last[1] + '" r="2.5"></circle></svg>';
  };
  const kpiCard = (k) => '<button type="button" class="kpi" data-tone="' + k.tone + '" data-action="sop:drill" data-kind="' + esc(k.title) + '"><span class="kpi__heading"><span class="kpi__title">' + esc(k.title) + '</span><iconify-icon noobserver icon="' + k.icon + '" aria-hidden="true"></iconify-icon></span><span class="kpi__body"><span class="kpi__main"><strong class="kpi__value">' + esc(k.value) + '</strong><span class="kpi__comparison"><small>' + esc(k.small) + '</small></span></span>' + spark(k.spark, k.tone) + '</span></button>';
  const kpiRow = (id) => '<div class="kpi-row">' + (KPIS[id] || []).slice(0, 3).map(kpiCard).join('') + '</div>';

  const tabsEl = root.querySelector('#sales-tabs');
  const panelsEl = root.querySelector('#sales-panels');
