  const fileIcon = (name) => { const e = name.split('.').pop().toLowerCase(); if (e === 'xlsx' || e === 'xls' || e === 'csv') return 'lucide:table'; if (e === 'fig') return 'lucide:layout-template'; if (e === 'docx' || e === 'doc') return 'lucide:file-text'; return 'lucide:file-text'; };
  const fmState = { project: 'Implementasi ERP', query: '' };
  const fmProjects = () => Object.keys(DOC_FILES);
  function renderFm(panel) {
    if (!panel) return;
    const side = panel.querySelector('[data-fm-side]'); const main = panel.querySelector('[data-fm-main]'); if (!side || !main) return;
    side.innerHTML = fmProjects().map(p => '<button type="button" class="fm-folder" data-fm-project="' + esc(p) + '" aria-selected="' + (p === fmState.project) + '"><iconify-icon noobserver icon="lucide:' + (p === fmState.project ? 'folder-open' : 'folder') + '" aria-hidden="true"></iconify-icon><span>' + esc(p) + '</span><span class="bd-count">' + (DOC_FILES[p] || []).length + '</span></button>').join('');
    const files = (DOC_FILES[fmState.project] || []).filter(f => !fmState.query || f.join(' ').toLowerCase().includes(fmState.query.toLowerCase()));
    const rows = files.length ? files.map(f => '<div class="fm-file"><iconify-icon noobserver icon="' + fileIcon(f[0]) + '" aria-hidden="true"></iconify-icon><span class="fm-file__name">' + esc(f[0]) + '</span><span class="chip ' + chipClass(f[5]) + '">' + esc(f[5]) + '</span><span class="fm-file__meta">' + esc(f[1]) + ' · ' + esc(f[2]) + ' · ' + esc(f[3]) + ' · ' + esc(f[4]) + '</span><button type="button" class="bd-rowbtn" data-fm-act="view" data-fm-name="' + esc(f[0]) + '">Lihat</button></div>').join('') : '<p class="card-list__empty">Folder ini kosong.</p>';
    main.innerHTML = '<div class="fm-crumb"><iconify-icon noobserver icon="lucide:folder-open" aria-hidden="true"></iconify-icon> Project <iconify-icon noobserver icon="lucide:chevron-right" aria-hidden="true"></iconify-icon> <strong>' + esc(fmState.project) + '</strong> <span class="bd-count">· ' + files.length + ' file</span></div>' + rows;
  }
  const tabsEl = root.querySelector('#proj-tabs');
