  const dialog = root.querySelector('dialog');
  const show = (title, description, bodyHtml) => { if (!dialog) { toast(title); return; } dialog.querySelector('[data-detail="title"]').textContent = title || ''; dialog.querySelector('[data-detail="description"]').textContent = description || ''; dialog.querySelector('[data-detail="body"]').innerHTML = bodyHtml || ''; dialog.showModal(); };
