  const spark = (points) => {
    const w = 90, h = 40, max = Math.max(...points), min = Math.min(...points);
    const span = (max - min) || 1;
    const coords = points.map((p, i) => { const x = (i / (points.length - 1)) * w; const y = h - 4 - ((p - min) / span) * (h - 8); return [x.toFixed(1), y.toFixed(1)]; });
    const line = coords.map(c => c.join(',')).join(' ');
    const last = coords[coords.length - 1];
    return '<svg class="kpi__spark" viewBox="0 0 ' + w + ' ' + h + '" preserveAspectRatio="none" aria-hidden="true"><polygon class="kpi__spark-area" points="' + line + ' ' + w + ',' + h + ' 0,' + h + '"></polygon><polyline class="kpi__spark-line" points="' + line + '"></polyline><circle class="kpi__spark-dot" cx="' + last[0] + '" cy="' + last[1] + '" r="2.5"></circle></svg>';
  };
