  const pageTitle = root.dataset.pageTitle || 'Reports & Analytics';
  const pageTitleEn = root.dataset.pageTitleEn || pageTitle;
  const crumb = root.querySelector('[data-part="crumb-page"]');
  
  root.querySelectorAll('[data-en]').forEach(el => { if (!el.dataset.id) el.dataset.id = el.textContent.trim(); });
  const applyLang = (lang) => { const en = lang === 'en'; root.querySelectorAll('[data-en]').forEach(el => { el.textContent = en ? el.dataset.en : el.dataset.id; });  document.documentElement.lang = en ? 'en' : 'id'; root.setAttribute('lang', en ? 'en' : 'id'); };
  document.addEventListener('nuvio:langchange', e => applyLang(e.detail && e.detail.lang));
  try { const saved = localStorage.getItem('sop-lang'); if (saved) applyLang(saved); } catch {}

