    kpi: { title: 'Company KPI scorecard', cols: ['KPI', 'Unit', 'Achievement', 'Target', 'Status'], rows: [['Revenue growth', 'Sales', '106%', '100%', 'On track'], ['Gross margin', 'Finance', '41%', '38%', 'On track'], ['On-time delivery', 'Project', '92%', '95%', 'At risk'], ['Stock accuracy', 'Inventory', '98%', '99%', 'On track'], ['Cash conversion', 'Finance', '88%', '90%', 'At risk'], ['Employee KPI', 'HR', '94%', '90%', 'On track']] },
