    pipeline: { title: 'Pipeline overview', cols: ['Stage', 'Opportunity', 'Nilai', 'Probabilitas', 'Status'], rows: [['Prospecting', '18', 'Rp 950 jt', '15%', 'On track'], ['Qualification', '11', 'Rp 1,24 M', '42%', 'On track'], ['Proposal', '8', 'Rp 1,51 M', '60%', 'On track'], ['Negotiation', '4', 'Rp 1,86 M', '78%', 'On track'], ['Won', '6', 'Rp 1,86 M', '100%', 'Done']] },
