    // PostgreSQL-backed data state, without changing the native UI/UX.
  window.SOPModules?.register('/document-management','page', () => ({FOLDERS,FILES,VERSIONS,APPROVALS,SIGNATURES,TEMPLATES}), v => { if (Array.isArray(FOLDERS) && Array.isArray(v.FOLDERS)) FOLDERS.splice(0,FOLDERS.length,...v.FOLDERS); else if (v.FOLDERS && typeof v.FOLDERS==='object') Object.assign(FOLDERS,v.FOLDERS); if (Array.isArray(FILES) && Array.isArray(v.FILES)) FILES.splice(0,FILES.length,...v.FILES); else if (v.FILES && typeof v.FILES==='object') Object.assign(FILES,v.FILES); if (Array.isArray(VERSIONS) && Array.isArray(v.VERSIONS)) VERSIONS.splice(0,VERSIONS.length,...v.VERSIONS); else if (v.VERSIONS && typeof v.VERSIONS==='object') Object.assign(VERSIONS,v.VERSIONS); if (Array.isArray(APPROVALS) && Array.isArray(v.APPROVALS)) APPROVALS.splice(0,APPROVALS.length,...v.APPROVALS); else if (v.APPROVALS && typeof v.APPROVALS==='object') Object.assign(APPROVALS,v.APPROVALS); if (Array.isArray(SIGNATURES) && Array.isArray(v.SIGNATURES)) SIGNATURES.splice(0,SIGNATURES.length,...v.SIGNATURES); else if (v.SIGNATURES && typeof v.SIGNATURES==='object') Object.assign(SIGNATURES,v.SIGNATURES); if (Array.isArray(TEMPLATES) && Array.isArray(v.TEMPLATES)) TEMPLATES.splice(0,TEMPLATES.length,...v.TEMPLATES); else if (v.TEMPLATES && typeof v.TEMPLATES==='object') Object.assign(TEMPLATES,v.TEMPLATES); });

const tabsEl = root.querySelector('#doc-tabs');
