  if (dialog) dialog.addEventListener('click', e => { if (e.target === dialog) { const r = dialog.getBoundingClientRect(); if (e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom) dialog.close(); } });

  const enterFrame = requestAnimationFrame(() => { if (reduceMotion.matches) return; const st = getComputedStyle(root); const d = parseFloat(st.getPropertyValue('--duration-panel')); const sd = parseFloat(st.getPropertyValue('--duration-stagger')); root.querySelectorAll('.page-head, .ws-tabs, .tabpanel:not([hidden])').forEach((region, i) => region.animate([{ opacity: 0, transform: 'translateY(6px)' }, { opacity: 1, transform: 'translateY(0)' }], { duration: d, delay: i * sd, easing: st.getPropertyValue('--ease-standard').trim(), fill: 'backwards' })); root.dispatchEvent(new CustomEvent('nuvio:enter', { bubbles: true })); });
  onCleanup(() => { cancelAnimationFrame(enterFrame); clearTimeout(toastTimer); });
