  try { const saved = localStorage.getItem('sop-lang'); if (saved) applyLang(saved); } catch {}

  document.addEventListener('click', e => { const el = e.target.closest('[data-action="kravio:sidebar"]'); if (!el) return; const mobile = small.matches; const cur = root.dataset.sidebar; const next = mobile ? (cur === 'open' ? 'closed' : 'open') : (cur === 'collapsed' ? 'default' : 'collapsed'); root.dataset.sidebar = next; el.setAttribute('aria-expanded', String(next !== 'closed')); });
  const aside = root.querySelector('[data-component="kravio-sidebar"]');
  if (aside) { let tip; const hide = () => { if (tip) tip.hidden = true; }; aside.addEventListener('pointerover', e => { if (root.dataset.sidebar !== 'collapsed') return; const el = e.target.closest('summary, button'); if (!el) return; const span = el.querySelector('span'); const label = span ? span.textContent.trim() : el.textContent.trim(); if (!label) return; if (!tip) { tip = document.createElement('div'); tip.className = 'kravio-sidebar-tip'; tip.setAttribute('role', 'tooltip'); document.body.appendChild(tip); } tip.textContent = label; tip.hidden = false; const r = el.getBoundingClientRect(); tip.style.top = (r.top + r.height / 2) + 'px'; tip.style.left = (r.right + 10) + 'px'; }); aside.addEventListener('pointerout', e => { if (!e.relatedTarget || !aside.contains(e.relatedTarget)) hide(); }); window.addEventListener('scroll', hide, true); }

  const CH = { whatsapp: { c: '#25D366', i: 'lucide:message-circle', n: 'WhatsApp', tone: 'done' }, email: { c: '#2b579a', i: 'lucide:mail', n: 'Email', tone: 'info' }, webchat: { c: '#7456b8', i: 'lucide:message-square', n: 'Web Chat', tone: 'progress' }, social: { c: '#c0392b', i: 'lucide:instagram', n: 'Social Media', tone: 'risk' } };

