  const donut = (v) => { const R = 60, C = 2 * Math.PI * R; let off = 0; const segs = v.items.map(it => { const len = (C * it[1]) / 100; const s = '<circle class="seg" cx="75" cy="75" r="' + R + '" stroke="' + it[2] + '" stroke-dasharray="' + len.toFixed(1) + ' ' + (C - len).toFixed(1) + '" stroke-dashoffset="' + (-off).toFixed(1) + '"></circle>'; off += len; return s; }).join(''); const legend = v.items.map(it => '<span><i style="background:' + it[2] + '"></i>' + esc(it[0]) + '<b>' + it[1] + '%</b></span>').join(''); return '<div class="donutwrap"><div class="donut"><svg viewBox="0 0 150 150"><circle class="track" cx="75" cy="75" r="' + R + '"></circle>' + segs + '</svg><div class="donut__center"><strong>' + esc(v.total) + '</strong><span>' + esc(v.title) + '</span></div></div><div class="donut__legend">' + legend + '</div></div>'; };

