  panelsEl.innerHTML = MENU.map((m, i) => '<section class="tabpanel" role="tabpanel" id="dash-panel-' + m.id + '" aria-labelledby="ws-tab-' + m.id + '" data-tabpanel="' + m.id + '" tabindex="0"' + (i === 0 ? '' : ' hidden') + '>' + kpiRow(m.id) + sectionFor(m) + '</section>').join('');
