  const selectTab = (id, focus) => { tabs.forEach(t => { const on = t.dataset.tab === id; t.setAttribute('aria-selected', String(on)); t.tabIndex = on ? 0 : -1; if (on && focus) t.focus(); }); panels.forEach(p => { p.hidden = p.dataset.tabpanel !== id; }); };
  tabs.forEach(t => t.addEventListener('click', () => selectTab(t.dataset.tab, false)));
  tabs.forEach(t => t.addEventListener('keydown', e => { const i = tabs.indexOf(t); if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') { e.preventDefault(); const n = e.key === 'ArrowRight' ? (i + 1) % tabs.length : (i - 1 + tabs.length) % tabs.length; selectTab(tabs[n].dataset.tab, true); } if (e.key === 'Home') { e.preventDefault(); selectTab(tabs[0].dataset.tab, true); } if (e.key === 'End') { e.preventDefault(); selectTab(tabs[tabs.length - 1].dataset.tab, true); } }));
