    const act = e.target.closest('[data-wa-act]'); if (act) { const a = act.dataset.waAct; if (a === 'send') { const st = chatState.x; const cur = CHAT.find(c => c.id === st.id); if (cur && st.reply.trim()) { cur.messages.push(['out', st.reply.trim(), 'Baru saja']); st.reply = ''; renderChat(); toast('Pesan WhatsApp terkirim.'); } else { toast('Tulis pesan dulu.'); } } else if (a === 'template') show('Message template', 'Pilih template provider-compliant.', '<ul style="margin:0;padding-left:18px;font-size:12px;color:var(--color-secondary)">' + TEMPLATES.map(t => '<li><b>' + esc(t[0]) + '</b> · ' + esc(t[1]) + '</li>').join('') + '</ul>'); else if (a === 'assign') toast('Membuka panel assignment.'); return; }
    const el = e.target.closest('[data-action]'); if (!el) return; const action = el.dataset.action;
    if (action === 'wa:sync') toast('Akun WhatsApp disinkronkan.');
