    if (m.id === 'cleaning') return '<div class="two-col"><section class="section-card"><div class="section-card__heading"><h3><iconify-icon noobserver icon="lucide:sparkles" aria-hidden="true"></iconify-icon>Data Cleaning</h3></div><div class="section-card__body"><div class="list-plain">' + d.cleaning.map(c => '<div class="list-item"><iconify-icon noobserver icon="lucide:sparkles" aria-hidden="true"></iconify-icon><div class="list-body"><p class="list-title">' + esc(c[0]) + '</p><p class="list-meta">' + esc(c[2]) + '</p></div><span class="chip info">' + esc(c[1]) + '</span></div>').join('') + '</div></div></section><section class="info-card"><h3><iconify-icon noobserver icon="lucide:check-circle-2" aria-hidden="true"></iconify-icon>Kualitas data</h3>' + barList([['Sebelum cleaning', 72, 'amber', '72%'], ['Setelah cleaning', 94, '', '94%'], ['Field lengkap', 88, 'teal', '88%'], ['Akurasi', 96, 'blue', '96%']]) + '</section></div>';
