    if (m.id === 'access') return '<section class="section-card"><div class="section-card__heading"><h3><iconify-icon noobserver icon="lucide:door-open" aria-hidden="true"></iconify-icon>Access Logs</h3></div><div class="section-card__body">' + tableHtml(['Waktu', 'Aktor', 'Method', 'Endpoint', 'Code', 'Keputusan'], DATA.access.map(r => [r[0], r[1], r[2], '<span class="code">' + esc(r[3]) + '</span>', r[4], '<span class="chip ' + (r[5] === 'allow' ? 'done' : r[5] === 'masked' ? 'pending' : 'risk') + '">' + esc(r[5]) + '</span>'])) + '</div></section>' + '<div class="two-col" style="margin-top:14px"><section class="info-card"><h3><iconify-icon noobserver icon="lucide:activity" aria-hidden="true"></iconify-icon>Distribusi keputusan</h3>' + barList([['Allow', 98, 'green', '2.097'], ['Deny', 2, 'red', '43'], ['Masked', 6, 'amber', '128']]) + '</section><section class="info-card"><h3><iconify-icon noobserver icon="lucide:shield-check" aria-hidden="true"></iconify-icon>Field-level permission</h3>' + barList([['Margin', 100, 'amber', 'Masked'], ['Bank account', 100, 'amber', 'Masked'], ['Tax ID', 100, 'amber', 'Masked'], ['Salary', 100, 'red', 'Hidden']]) + '</section></div>';
    if (m.id === 'change') return '<section class="section-card"><div class="section-card__heading"><h3><iconify-icon noobserver icon="lucide:file-diff" aria-hidden="true"></iconify-icon>Data Change History</h3><span class="chip info">640 perubahan</span></div><div class="section-card__body">' + tableHtml(['Waktu', 'Entity', 'Field', 'Sebelum', 'Sesudah', 'Oleh'], DATA.change.map(r => [r[0], r[1], r[2], '<span class="diff del">' + esc(r[3]) + '</span>', '<span class="diff add">' + esc(r[4]) + '</span>', r[5]])) + '</div></section>' + '<div class="two-col" style="margin-top:14px"><section class="info-card"><h3><iconify-icon noobserver icon="lucide:history" aria-hidden="true"></iconify-icon>Perubahan per modul</h3>' + barList([['Sales', 38, 'blue', '38%'], ['Finance', 26, '', '26%'], ['Inventory', 18, 'teal', '18%'], ['Master data', 12, 'violet', '12%'], ['Lainnya', 6, 'amber', '6%']]) + '</section><section class="info-card"><h3><iconify-icon noobserver icon="lucide:git-commit" aria-hidden="true"></iconify-icon>Versioning &amp; rollback</h3>' + barList([['Versi tersimpan', 100, '', '1.280'], ['Rollback tersedia', 100, 'green', '3'], ['Perlu approval', 100, 'amber', '12'], ['Audit lengkap', 100, '', '100%']]) + '</section></div>';
    if (m.id === 'events') return '<section class="section-card"><div class="section-card__heading"><h3><iconify-icon noobserver icon="lucide:shield-alert" aria-hidden="true"></iconify-icon>Security Events</h3><span class="chip risk">3 perlu tindakan</span></div><div class="section-card__body">' + tableHtml(['Waktu', 'Event', 'Severity', 'Tindakan', 'Status'], DATA.events.map(r => [r[0], r[1], '<span class="sev ' + sevClass(r[2]) + '">' + esc(r[2]) + '</span>', r[3], '<span class="chip ' + (r[4] === 'Resolved' ? 'done' : 'pending') + '">' + esc(r[4]) + '</span>'])) + '</div></section>' + '<div class="two-col" style="margin-top:14px"><section class="info-card"><h3><iconify-icon noobserver icon="lucide:bar-chart-3" aria-hidden="true"></iconify-icon>Event per hari</h3>' + barsV() + '</section><section class="info-card"><h3><iconify-icon noobserver icon="lucide:shield" aria-hidden="true"></iconify-icon>Postur keamanan</h3>' + barList([['MFA/SSO', 88, 'green', '88%'], ['Least privilege', 94, '', '94%'], ['Encryption', 100, 'green', 'Aktif'], ['Security scan', 96, 'teal', '96%']]) + '</section></div>';
